B.cdV=s(["Aquel d\xeda el campo perteneci\xf3 a un solo jugador","Despedirse cuando m\xe1s brillan las luces","Sin tiempo para deshacer las maletas","Aquel a\xf1o, todo el mundo conoc\xeda ese nombre","Siempre junto al podio","Ni ganar ni perder","Arriba, abajo y otra vez arriba","Un a\xf1o que nadie quiere recordar","El a\xf1o en que la porter\xeda parec\xeda diminuta","A un paso del trofeo","Los votos llegaron. El trofeo no.","El \xfaltimo partido fue el m\xe1s largo"],t.s)
B.bIJ=s(["Naquele dia, o campo pertenceu a um s\xf3 jogador","Sair quando as luzes brilham mais","Sem tempo de desfazer as malas","Naquele ano, todo mundo conhecia o nome","Sempre ao lado do p\xf3dio","Nem vit\xf3ria, nem derrota","Para cima, para baixo e para cima de novo","Um ano que ningu\xe9m quer lembrar","O ano em que o gol parecia min\xfasculo","A um passo do trof\xe9u","Os votos vieram. O trof\xe9u n\xe3o.","A \xfaltima partida foi a mais longa"],t.s)
B.bWD=s(["Ce jour-l\xe0, le terrain appartenait \xe0 un seul joueur","Partir quand les lumi\xe8res brillent le plus","Jamais le temps de d\xe9faire les valises","Cette ann\xe9e-l\xe0, tout le monde connaissait ce nom","Toujours au pied du podium","Ni victoire ni d\xe9faite","En haut, en bas, puis en haut","Une ann\xe9e \xe0 oublier","L'ann\xe9e o\xf9 le but semblait minuscule","\xc0 un pas du troph\xe9e","Les voix \xe9taient l\xe0. Pas le troph\xe9e.","Le dernier match \xe9tait le plus long"],t.s)
B.bSx=s(["An diesem Tag geh\xf6rte der Platz einem einzigen Spieler","Gehen, wenn die Lichter am hellsten leuchten","Nie ganz ausgepackt","In diesem Jahr kannte die Welt diesen Namen","Immer direkt neben dem Podium","Weder Sieg noch Niederlage","Hoch, runter und wieder hoch","Ein Jahr zum Vergessen","Das Jahr, in dem das Tor winzig wirkte","Nur einen Schritt vom Pokal entfernt","Die Stimmen waren da. Die Troph\xe4e nicht.","Das letzte Spiel war das l\xe4ngste"],t.s)
B.cl6=s(["Quel giorno il campo apparteneva a un solo giocatore","Andarsene quando le luci brillano di pi\xf9","Mai il tempo di disfare le valigie","Quell'anno tutti conoscevano quel nome","Sempre accanto al podio","N\xe9 vittoria n\xe9 sconfitta","Su, gi\xf9 e di nuovo su","Un anno da dimenticare","L'anno in cui la porta sembrava minuscola","A un passo dal trofeo","I voti c'erano. Il trofeo no.","L'ultima partita \xe8 stata la pi\xf9 lunga"],t.s)
B.c9u=s(["Hari itu lapangan milik satu pemain saja","Pergi saat sorotan paling terang","Belum sempat membongkar koper","Tahun itu semua orang mengenal namanya","Selalu tepat di samping podium","Tak menang, tak kalah","Naik, turun, lalu naik lagi","Tahun yang tak ingin dikenang","Tahun ketika gawang tampak kecil","Selangkah dari trofi","Suara sudah ada. Trofinya tidak.","Laga terakhir terasa paling panjang"],t.s)
