B.bQ5=s(["\u0623\u0643\u0645\u0644 \u0627\u0644\u0634\u0627\u0631\u0627\u062a \u0648GOAT \u0628\u062c\u0645\u0639 \u0627\u0644\u0623\u0644\u0642\u0627\u0628 \u0627\u0644\u0623\u0633\u0627\u0633\u064a\u0629 \u0627\u0644\u064074.","\u062a\u064f\u0645\u0646\u062d \u0644\u0623\u0641\u0636\u0644 3 \u0623\u0633\u0628\u0648\u0639\u064a\u064b\u0627 \u0623\u0648 \u0623\u0641\u0636\u0644 10% \u0623\u0648 30% \u0623\u0648 \u0644\u062d\u0627\u0645\u0644\u064a \u0623\u0631\u0642\u0627\u0645 \u0627\u0644\u0645\u0648\u0633\u0645.","\u0644\u0623\u0641\u0636\u0644 3 \u0648\u0623\u0641\u0636\u0644 10% \u064830% \u0641\u064a \u0627\u0644\u0645\u0648\u0633\u0645 \u0627\u0644\u0623\u0633\u0628\u0648\u0639\u064a.","\u0644\u062d\u0627\u0645\u0644 \u0627\u0644\u0631\u0642\u0645 \u0627\u0644\u0642\u064a\u0627\u0633\u064a \u0641\u064a \u0643\u0644 \u0641\u0626\u0629 \u0639\u0646\u062f \u0646\u0647\u0627\u064a\u0629 \u0627\u0644\u0645\u0648\u0633\u0645.","\u0644\u0623\u0635\u062d\u0627\u0628 \u0627\u0644\u0623\u0631\u0642\u0627\u0645 \u063a\u064a\u0631 \u0627\u0644\u0645\u0639\u062a\u0627\u062f\u0629 \u0639\u0646\u062f \u0646\u0647\u0627\u064a\u0629 \u0627\u0644\u0645\u0648\u0633\u0645.","\u0627\u0631\u062a\u062f\u0627\u0621 \u0627\u0644\u0634\u0627\u0631\u0629","\u0627\u0644\u0634\u0627\u0631\u0629 \u0645\u062c\u0647\u0651\u0632\u0629","\u0625\u063a\u0644\u0627\u0642 \u0627\u0644\u0628\u062d\u062b"],t.s)
